/// `(first code, last code, CID of the first code)`; the CID rises with the
/// code across the run.
type Run = (u16, u16, u16);

/// One bundled predefined CMap.
#[derive(Debug)]
pub(crate) struct PredefinedCMap {
    runs: &'static [Run],
    base: Option<&'static [Run]>,
}

impl PredefinedCMap {
    /// The CID `code` selects, or `None` when the CMap does not map it.
    pub(crate) fn cid(&self, code: u16) -> Option<u16> {
        find(self.runs, code).or_else(|| self.base.and_then(|base| find(base, code)))
    }
}

fn find(runs: &[Run], code: u16) -> Option<u16> {
    let idx = runs.partition_point(|&(_, last, _)| last < code);
    let &(first, _, cid) = runs.get(idx)?;
    (first <= code).then(|| cid + (code - first))
}

/// The CMap names bundled here.
#[cfg(test)]
const NAMES: [&str; 22] = [
    "83pv-RKSJ-H",
    "90ms-RKSJ-H",
    "90ms-RKSJ-V",
    "90msp-RKSJ-H",
    "90msp-RKSJ-V",
    "90pv-RKSJ-H",
    "Add-RKSJ-H",
    "Add-RKSJ-V",
    "EUC-H",
    "EUC-V",
    "Ext-RKSJ-H",
    "Ext-RKSJ-V",
    "H",
    "V",
    "UniJIS-UCS2-H",
    "UniJIS-UCS2-V",
    "UniJIS-UCS2-HW-H",
    "UniJIS-UCS2-HW-V",
    "UniJIS-UTF16-H",
    "UniJIS-UTF16-V",
    "UniJIS2004-UTF16-H",
    "UniJIS2004-UTF16-V",
];

/// The bundled CMap of that name, or `None` for a name not bundled here
/// (Identity-H/V, the other collections' CMaps, anything unknown).
pub(crate) fn lookup(name: &str) -> Option<PredefinedCMap> {
    let (runs, base): (&'static [Run], Option<&'static [Run]>) = match name {
        "83pv-RKSJ-H" => (&CMAP_83PV_RKSJ_H, None),
        "90ms-RKSJ-H" => (&CMAP_90MS_RKSJ_H, None),
        "90ms-RKSJ-V" => (&CMAP_90MS_RKSJ_V, Some(&CMAP_90MS_RKSJ_H)),
        "90msp-RKSJ-H" => (&CMAP_90MSP_RKSJ_H, None),
        "90msp-RKSJ-V" => (&CMAP_90MSP_RKSJ_V, Some(&CMAP_90MSP_RKSJ_H)),
        "90pv-RKSJ-H" => (&CMAP_90PV_RKSJ_H, None),
        "Add-RKSJ-H" => (&CMAP_ADD_RKSJ_H, None),
        "Add-RKSJ-V" => (&CMAP_ADD_RKSJ_V, Some(&CMAP_ADD_RKSJ_H)),
        "EUC-H" => (&CMAP_EUC_H, None),
        "EUC-V" => (&CMAP_EUC_V, Some(&CMAP_EUC_H)),
        "Ext-RKSJ-H" => (&CMAP_EXT_RKSJ_H, None),
        "Ext-RKSJ-V" => (&CMAP_EXT_RKSJ_V, Some(&CMAP_EXT_RKSJ_H)),
        "H" => (&CMAP_H, None),
        "V" => (&CMAP_V, Some(&CMAP_H)),
        "UniJIS-UCS2-H" => (&CMAP_UNIJIS_UCS2_H, None),
        "UniJIS-UCS2-V" => (&CMAP_UNIJIS_UCS2_V, Some(&CMAP_UNIJIS_UCS2_H)),
        "UniJIS-UCS2-HW-H" => (&CMAP_UNIJIS_UCS2_HW_H, Some(&CMAP_UNIJIS_UCS2_H)),
        "UniJIS-UCS2-HW-V" => (&CMAP_UNIJIS_UCS2_HW_V, Some(&CMAP_UNIJIS_UCS2_H)),
        "UniJIS-UTF16-H" => (&CMAP_UNIJIS_UTF16_H, None),
        "UniJIS-UTF16-V" => (&CMAP_UNIJIS_UTF16_V, Some(&CMAP_UNIJIS_UTF16_H)),
        "UniJIS2004-UTF16-H" => (&CMAP_UNIJIS2004_UTF16_H, None),
        "UniJIS2004-UTF16-V" => (&CMAP_UNIJIS2004_UTF16_V, Some(&CMAP_UNIJIS2004_UTF16_H)),
        _ => return None,
    };
    Some(PredefinedCMap { runs, base })
}

