#[cfg(test)]
mod tests {
    use super::*;

    fn cid(name: &str, code: u16) -> Option<u16> {
        lookup(name).expect("bundled").cid(code)
    }

    #[test]
    fn identity_and_unknown_names_are_not_bundled() {
        assert!(lookup("Identity-H").is_none());
        assert!(lookup("Identity-V").is_none());
        assert!(lookup("GBK-EUC-H").is_none());
    }

    #[test]
    fn unicode_cmaps_map_a_code_to_its_adobe_japan1_cid() {
        // Proportional Latin and digits are CIDs 1..=95, not the code.
        assert_eq!(cid("UniJIS-UCS2-H", 0x0020), Some(1));
        assert_eq!(cid("UniJIS-UCS2-H", 0x0032), Some(19));
        assert_eq!(cid("UniJIS-UCS2-H", 0x0041), Some(34));
        assert_eq!(cid("UniJIS-UCS2-H", 0x3042), Some(843)); // HIRAGANA LETTER A
        assert_eq!(cid("UniJIS-UCS2-H", 0x4E00), Some(1200)); // CJK ideograph "one"
        assert_eq!(cid("UniJIS-UTF16-H", 0x0041), Some(34));
        assert_eq!(cid("UniJIS2004-UTF16-H", 0x3042), Some(843));
        // The half-width variant sends ASCII to the half-width CIDs.
        assert_eq!(cid("UniJIS-UCS2-HW-H", 0x0041), Some(264));
        assert_eq!(cid("UniJIS-UCS2-HW-H", 0x3042), Some(843)); // from the base
    }

    #[test]
    fn shift_jis_cmaps_tell_half_width_from_proportional() {
        // 90ms: single-byte codes are the half-width CIDs 231..
        assert_eq!(cid("90ms-RKSJ-H", 0x20), Some(231));
        assert_eq!(cid("90ms-RKSJ-H", 0x41), Some(264));
        // 90msp: the same codes are the proportional CIDs 1..
        assert_eq!(cid("90msp-RKSJ-H", 0x20), Some(1));
        assert_eq!(cid("90msp-RKSJ-H", 0x41), Some(34));
        // A two-byte code: 0x82A0 is HIRAGANA LETTER A.
        assert_eq!(cid("90ms-RKSJ-H", 0x82A0), Some(843));
        assert_eq!(cid("90msp-RKSJ-H", 0x82A0), Some(843));
        // 0x889F is the first level-1 kanji.
        assert_eq!(cid("90ms-RKSJ-H", 0x889F), Some(1125));
    }

    #[test]
    fn a_vertical_cmap_overrides_its_base_and_reads_the_rest_through_it() {
        // 0x8141 (IDEOGRAPHIC COMMA) has a vertical glyph.
        assert_eq!(cid("90ms-RKSJ-H", 0x8141), Some(634));
        assert_eq!(cid("90ms-RKSJ-V", 0x8141), Some(7887));
        // A kana is the same glyph in both writing modes.
        assert_eq!(cid("90ms-RKSJ-V", 0x82A0), Some(843));
    }

    #[test]
    fn an_unmapped_code_has_no_cid() {
        assert_eq!(cid("90ms-RKSJ-H", 0xFFFF), None);
        assert_eq!(cid("H", 0x0041), None); // JIS X 0208 row-cell codes only
    }

    #[test]
    fn runs_are_sorted_and_disjoint() {
        for name in NAMES {
            let cmap = lookup(name).unwrap();
            for runs in [Some(cmap.runs), cmap.base].into_iter().flatten() {
                for pair in runs.windows(2) {
                    assert!(pair[0].1 < pair[1].0, "{name}: {:?} then {:?}", pair[0], pair[1]);
                }
                for &(first, last, cid) in runs {
                    assert!(first <= last, "{name}");
                    assert!(cid.checked_add(last - first).is_some(), "{name}");
                }
            }
        }
    }
}
